/** static void SpriteCB_Ball_Arc(struct Sprite *sprite) */
export function SpriteCB_Ball_Arc(sprite: any): any {
  let i: any = null;
      let ballId: any = null;

      if (TranslateAnimHorizontalArc(sprite))
      {
          if (gBattleSpritesDataPtr.animationData.ballThrowCaseId == BALL_TRAINER_BLOCK)
          {
              sprite.callback = SpriteCB_Ball_Block;
          }
          else
          {
              StartSpriteAnim(sprite, 1);
              sprite.x += sprite.x2;
              sprite.y += sprite.y2;
              sprite.x2 = 0;
              sprite.y2 = 0;

              for (i = 0; i < 8; i++)
                  sprite.data[i] = 0;

              sprite.sTimer = 0;
              sprite.callback = SpriteCB_Ball_MonShrink;

              ballId = ItemIdToBallId(gLastUsedItem);
              switch (ballId)
              {
              case 0:
                  AnimateBallOpenParticles(sprite.x, sprite.y - 5, 1, 28, ballId);
                  LaunchBallFadeMonTask(FALSE, gBattleAnimTarget, 14, ballId);
                  break;
              }
          }
      }
}

